sys_script_include.script:
var TrainingRegistrationUtils = Class.create();
TrainingRegistrationUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    isUserAlreadyRegistered: function() {
        var userId = this.getParameter('sysparm_user_id');
        var courseId = this.getParameter('sysparm_course_id'); 
        var trainingDate = this.getParameter('sysparm_training_date');

        var gr = new GlideRecord('x_1567520_shark_0_registration');
        gr.addQuery('user', userId);
        gr.addQuery('course', courseId); 
        gr.addQuery('schedule_date', trainingDate); 
        gr.query();

        return gr.hasNext() ? 'true' : 'false'; 
    },

    getAvailableCourses: function() {
        var userId = this.getParameter('sysparm_user_id'); 
        var trainingDate = this.getParameter('sysparm_training_date'); 
        var results = [];

        var gr = new GlideRecord('x_1567520_shark_0_training_course'); 
        gr.query();

        while (gr.next()) {
            var courseId = gr.sys_id;
            var isRegistered = this.isUserAlreadyRegistered(userId, courseId, trainingDate);

            if (isRegistered === 'false') {
                results.push({
                    sys_id: courseId.toString(),
                    course_name: gr.name.toString()
                });
            }
        }

        return JSON.stringify(results);
    },

    type: 'TrainingRegistrationUtils'
});
